<?php
require dirname(__DIR__).'/includes/bootstrap.php';$u=require_permission('XEM_BAO_CAO');$from=get('from')?:date('Y-m-01');$to=get('to')?:date('Y-m-d');$start=valid_date($from.' 00:00:00');$end=date('Y-m-d H:i:s',strtotime(valid_date($to.' 00:00:00'))+86400);must($end>$start&&strtotime($end)-strtotime($start)<=3*366*86400,'Khoảng thống kê tối đa 3 năm.');$cond=['1=1'];$p=[];if($u['quyen']!=='ADMIN'){$cond[]='h.ma_showroom_chot IN(SELECT ma_showroom FROM pham_vi_showroom WHERE tai_khoan_id=?)';$p[]=$u['id'];}foreach(['showroom'=>'h.ma_showroom_chot','nhan_vien'=>'COALESCE(h.nhan_vien_chot_id,h.nhan_vien_id)','dong'=>'x.ma_dong_xe']as$k=>$col)if(get($k)!==''){$cond[]="$col=?";$p[]=get($k);}$where=implode(' AND ',$cond);
$daily=db_all("SELECT DATE(h.ngay_ban_giao) ngay,COUNT(*) so_xe,SUM(h.tong_gia_tri) doanh_thu,SUM(CASE WHEN h.gia_von_chot IS NOT NULL THEN h.tong_gia_tri-h.gia_von_chot END) loi_nhuan,SUM(h.gia_von_chot IS NULL) thieu FROM hop_dong h JOIN xe x ON x.so_khung_vin=h.so_khung_vin WHERE h.trang_thai_hd='HOAN_TAT' AND h.ngay_ban_giao>=? AND h.ngay_ban_giao<? AND $where GROUP BY DATE(h.ngay_ban_giao) ORDER BY ngay",[$start,$end,...$p]);
$cash=db_one("SELECT COALESCE(SUM(CASE WHEN t.loai_giao_dich='THU' THEN t.so_tien_thu ELSE 0 END),0) thu,COALESCE(SUM(CASE WHEN t.loai_giao_dich='HOAN_TIEN' THEN t.so_tien_thu ELSE 0 END),0) hoan FROM hoa_don t JOIN hop_dong h ON h.so_hop_dong=t.so_hop_dong JOIN xe x ON x.so_khung_vin=h.so_khung_vin WHERE t.trang_thai='SUCCESS' AND t.ngay_thu>=? AND t.ngay_thu<? AND $where",[$start,$end,...$p]);
$debt=db_one("SELECT COALESCE(SUM(GREATEST(0,h.tong_gia_tri-COALESCE(a.net,0))),0) debt FROM hop_dong h JOIN xe x ON x.so_khung_vin=h.so_khung_vin LEFT JOIN(SELECT so_hop_dong,SUM(CASE WHEN loai_giao_dich='THU' THEN so_tien_thu ELSE -so_tien_thu END)net FROM hoa_don WHERE trang_thai='SUCCESS' GROUP BY so_hop_dong)a ON a.so_hop_dong=h.so_hop_dong WHERE h.trang_thai_hd IN ('DA_DAT_COC','DA_THANH_TOAN') AND $where",$p)['debt'];
$cc=['ngay_chi>=?','ngay_chi<?'];$cp=[$start,$end];if(get('showroom')){$cc[]='ma_showroom=?';$cp[]=get('showroom');}if($u['quyen']!=='ADMIN'){$cc[]='ma_showroom IN(SELECT ma_showroom FROM pham_vi_showroom WHERE tai_khoan_id=?)';$cp[]=$u['id'];}$spent=db_one('SELECT COALESCE(SUM(so_tien),0) n FROM chi_tien WHERE '.implode(' AND ',$cc),$cp)['n'];$revenue=array_sum(array_column($daily,'doanh_thu'));$profit=array_sum(array_column($daily,'loi_nhuan'));$missing=array_sum(array_column($daily,'thieu'));
page_start('Báo cáo kinh doanh','Doanh thu theo ngày bàn giao; tiền thu / hoàn theo ngày thực nhận.');echo '<form class="filters" method="get">';field('from','Từ ngày',$from,'date');field('to','Đến ngày',$to,'date');select_field('showroom','Showroom',choices('SELECT * FROM showroom','ma_showroom','ten_showroom'),get('showroom'));select_field('dong','Dòng xe',choices('SELECT * FROM dong_xe','ma_dong_xe','ten_dong_xe'),get('dong'));select_field('nhan_vien','Nhân viên',choices("SELECT id,ho_ten FROM tai_khoan WHERE quyen='NHAN_VIEN'",'id','ho_ten'),get('nhan_vien'));echo '<button>Xem báo cáo</button></form><div class="stats">';foreach(['Doanh thu bàn giao'=>$revenue,'Lợi nhuận gộp đã biết'=>$profit,'Tiền thu'=>$cash['thu'],'Tiền hoàn'=>$cash['hoan'],'Phải thu hiện tại'=>$debt]as$label=>$n)echo '<div class="stat"><span>'.e($label).'</span><b style="font-size:22px">'.e(money($n)).'</b></div>';echo '</div>';if($missing)notice('Có '.$missing.' xe thiếu giá vốn; lợi nhuận trên chỉ gồm xe có dữ liệu.');if(!get('dong')&&!get('nhan_vien'))notice('Chi thực tế: '.money($spent).' · Dòng tiền bán xe/vận hành: '.money((int)$cash['thu']-(int)$cash['hoan']-(int)$spent));else notice('Dòng tiền toàn phần chỉ hiển thị khi không lọc dòng xe/nhân viên, vì chi vận hành không phân bổ theo hai tiêu chí này.');
table_start(['Ngày','Xe đã giao','Doanh thu','So sánh']);$max=max(1,...array_column($daily,'doanh_thu'));foreach($daily as$r)echo '<tr><td>'.e($r['ngay']).'</td><td>'.(int)$r['so_xe'].'</td><td>'.e(money($r['doanh_thu'])).'</td><td style="width:35%"><div class="bar"><span style="width:'.round((float)$r['doanh_thu']/$max*100,1).'%"></span></div></td></tr>';table_end();
echo '<h2>Tồn kho lâu ngày</h2>';$iw=$u['quyen']==='ADMIN'?'1=1':'ma_showroom IN (SELECT ma_showroom FROM pham_vi_showroom WHERE tai_khoan_id='.(int)$u['id'].')';$ip=[];if(get('showroom')){$iw.=' AND ma_showroom=?';$ip[]=get('showroom');}if(get('dong')){$iw.=' AND ma_dong_xe=?';$ip[]=get('dong');}table_start(['VIN','Showroom','Ngày nhập đầu','Số ngày tồn']);foreach(db_all("SELECT so_khung_vin,ma_showroom,ngay_nhap_dau,DATEDIFF(NOW(),ngay_nhap_dau) days FROM xe WHERE trang_thai<>'DA_BAN_GIAO' AND $iw ORDER BY days DESC LIMIT 50",$ip)as$r)echo '<tr><td>'.e($r['so_khung_vin']).'</td><td>'.e($r['ma_showroom']).'</td><td>'.e($r['ngay_nhap_dau']).'</td><td>'.e($r['days']??'Chưa có dữ liệu').'</td></tr>';table_end();
$chatScope=$u['quyen']==='ADMIN'?'1=1':'c.nhan_vien_id='.(int)$u['id'];$cr=db_one("SELECT COUNT(*) total,SUM(EXISTS(SELECT 1 FROM hop_dong h WHERE h.ma_hoi_thoai=c.ma_hoi_thoai AND h.trang_thai_hd='HOAN_TAT')) converted FROM hoi_thoai_chat c WHERE c.ngay_tao>=? AND c.ngay_tao<? AND $chatScope",[$start,$end]);notice('Chuyển đổi hội thoại tạo trong kỳ, tính đến hiện tại: '.(int)$cr['converted'].' / '.(int)$cr['total'].' ('.($cr['total']?round($cr['converted']/$cr['total']*100,1):0).'%). Chỉ tiêu này dùng phạm vi nhân viên của người xem, không áp dụng bộ lọc dòng xe/showroom.');echo '<button class="ghost no-print" onclick="window.print()">In / Lưu báo cáo PDF</button>';page_end();
